import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    M = 10 ** 9 + 7
    g = data[2:]
    dp = [0] * c
    for i in range(r):
        row = g[i * c:(i + 1) * c]
        for j in range(c):
            if row[j] == '1':
                dp[j] = 0
            elif i == 0 and j == 0:
                dp[j] = 1
            elif j > 0:
                dp[j] = (dp[j] + dp[j - 1]) % M
    print(dp[c - 1] % M)

main()

